import React, { ReactNode, useEffect, useState } from "react";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import LanguageSelector from "./languageSelector";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import data from "../data/data.json";
import Sidebar from "../components/sidebar";

interface LayoutProps {
  children: ReactNode;
  data?: UserProfile;
}

const userData: UserProfile = data;

const Layout: React.FC<LayoutProps> = ({ children, data }) => {
  const { t } = useTranslation();
  const currentYear = new Date().getFullYear();
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 0);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(4, 7 )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <>
      <div id={data?.menu[0]} className={styles.container}>
        <Sidebar />
        {/* aplicar bg-primary cuando se haga scroll */}
        <div className={styles.header}>

          <a className={styles.logoContainer} href="/"> 
            <img
              src={images.logo.src}
              alt={images.logo.alt}
              className={styles.logo}
            />
          </a>
          <Navigation />
          <LanguageSelector data={userData} />
        </div>
        <div className="relative
        ">{children}</div>
      </div>

      <footer className={styles.footerContainer} id={userData.menu[4]}>
        <div className="flex flex-col sm:flex-row">
          <div className="flex flex-col w-full self-center">
            <div className="mx-auto p-4 text-white">
              &copy; {currentYear} {userData?.name}
            </div>
          </div>
        </div>
      </footer>
    </>
  );
};

export default Layout;

const styles = {
  container: "w-full flex flex-col mx-auto",
  header: "w-full h-auto  flex flex-row justify-center items-center py-4 sm:py-0  z-40 !top-gradient-light",
  logoContainer: "w-60 bg-white/80 mx-8 flex justify-center items-center relative px-4 py-2",
  logo: "sm:w-[22rem] h-auto rounded-2xl",
  footerContainer: "bg-secondary text-accent flex flex-col relative",
};
